<?php
declare(strict_types=1);

/**
 * Atelier Wood MakeOS Procurement — v0.7.2
 * Supplier master + raw material inventory + lots/batches + PO + GRN + stock reservations.
 */
function procurement_root(): string { return data_root().'/private-domain/procurement'; }
function procurement_file(): string { return procurement_root().'/store.json'; }
function procurement_context(): string { return 'atelierwood:procurement:v1'; }
function procurement_ensure_dirs(): void { $d=procurement_root(); if(!is_dir($d)&&!@mkdir($d,0750,true)&&!is_dir($d)) throw new RuntimeException('Unable to create procurement directory.'); @chmod($d,0750); }
function procurement_empty_store(): array { return ['suppliers'=>[],'materials'=>[],'purchase_orders'=>[],'grns'=>[],'lots'=>[],'reservations'=>[],'events'=>[]]; }
function procurement_store(): array { procurement_ensure_dirs(); try{$s=commerce_private_read(procurement_file(),procurement_context(),procurement_empty_store());}catch(Throwable){$s=procurement_empty_store();} return array_merge(procurement_empty_store(),$s); }
function procurement_mutate(callable $fn,string $reason): array { procurement_ensure_dirs(); $out=[]; commerce_private_mutate(procurement_file(),procurement_context(),function(array $s)use($fn,&$out){$s=array_merge(procurement_empty_store(),$s);$s=$fn($s);$out=$s;return$s;},$reason);return$out; }
function procurement_code(string $prefix): string { return $prefix.'-'.gmdate('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8)); }
function procurement_supplier_by_guid(string $guid): ?array { foreach(procurement_store()['suppliers'] as $x)if(($x['guid']??'')===$guid)return$x;return null; }
function procurement_material_by_guid(string $guid): ?array { foreach(procurement_store()['materials'] as $x)if(($x['guid']??'')===$guid)return$x;return null; }
function procurement_po_by_guid(string $guid): ?array { foreach(procurement_store()['purchase_orders'] as $x)if(($x['guid']??'')===$guid)return$x;return null; }
function procurement_reservation_by_guid(string $guid): ?array { foreach(procurement_store()['reservations'] as $x)if(($x['guid']??'')===$guid)return$x;return null; }
function procurement_suppliers(): array { $r=procurement_store()['suppliers']; usort($r,fn($a,$b)=>strcmp((string)$a['name'],(string)$b['name']));return$r; }
function procurement_materials(): array { $r=procurement_store()['materials']; usort($r,fn($a,$b)=>strcmp((string)$a['name'],(string)$b['name']));return$r; }
function procurement_lots(?string $materialGuid=null): array { $r=procurement_store()['lots']; if($materialGuid)$r=array_values(array_filter($r,fn($x)=>($x['material_guid']??'')===$materialGuid));usort($r,fn($a,$b)=>strcmp((string)($a['received_at']??''),(string)($b['received_at']??'')));return$r; }
function procurement_purchase_orders(): array { $r=procurement_store()['purchase_orders'];usort($r,fn($a,$b)=>strcmp((string)$b['created_at'],(string)$a['created_at']));return$r; }
function procurement_reservations_for_job(string $jobGuid): array { return array_values(array_filter(procurement_store()['reservations'],fn($x)=>($x['job_guid']??'')===$jobGuid&&($x['status']??'')!=='RELEASED')); }
function procurement_supplier_save(array $input,?string $guid=null): array { require_admin(); $name=trim((string)($input['name']??''));$phone=trim((string)($input['phone']??''));$email=trim((string)($input['email']??''));if($name==='')throw new RuntimeException('Supplier name is required.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Supplier email is invalid.');$row=['guid'=>$guid?:uuidv7(),'code'=>trim((string)($input['code']??''))?:procurement_code('SUP'),'name'=>$name,'phone'=>$phone,'email'=>$email,'gstin'=>strtoupper(trim((string)($input['gstin']??''))),'lead_days'=>max(0,(int)($input['lead_days']??0)),'active'=>!isset($input['active'])||!empty($input['active']),'notes'=>trim((string)($input['notes']??'')),'updated_at'=>gmdate('c')];$row['created_at']=gmdate('c');procurement_mutate(function(array $s)use($row,$guid){$found=false;foreach($s['suppliers'] as &$x)if(($x['guid']??'')===($guid??'')){$row2=$row;$row2['created_at']=$x['created_at']??$row['created_at'];$x=$row2;$found=true;break;}if(!$found)$s['suppliers'][]=$row;return$s;},'procurement.supplier.save');audit_event('procurement.supplier.save',['supplier_guid'=>$row['guid']]);return procurement_supplier_by_guid($row['guid'])??$row; }
function procurement_material_save(array $input,?string $guid=null): array { require_admin();$name=trim((string)($input['name']??''));$unit=trim((string)($input['unit']??''));if($name===''||$unit==='')throw new RuntimeException('Material name and unit are required.');$row=['guid'=>$guid?:uuidv7(),'code'=>strtoupper(trim((string)($input['code']??'')))?:procurement_code('MAT'),'name'=>$name,'type'=>strtoupper(trim((string)($input['type']??'MATERIAL'))),'unit'=>$unit,'reorder_level'=>max(0,(float)($input['reorder_level']??0)),'preferred_supplier_guid'=>trim((string)($input['preferred_supplier_guid']??'')),'active'=>!isset($input['active'])||!empty($input['active']),'notes'=>trim((string)($input['notes']??'')),'updated_at'=>gmdate('c'),'created_at'=>gmdate('c')];procurement_mutate(function(array $s)use($row,$guid){foreach($s['materials'] as $x){if(strtoupper((string)($x['code']??''))===strtoupper($row['code'])&&($x['guid']??'')!==($guid??''))throw new RuntimeException('Material code already exists.');}$found=false;foreach($s['materials'] as &$x)if(($x['guid']??'')===($guid??'')){$r=$row;$r['created_at']=$x['created_at']??$row['created_at'];$x=$r;$found=true;break;}if(!$found)$s['materials'][]=$row;return$s;},'procurement.material.save');audit_event('procurement.material.save',['material_guid'=>$row['guid']]);return procurement_material_by_guid($row['guid'])??$row; }
function procurement_po_create(string $supplierGuid,array $lines,string $notes=''): array { require_admin();$supplier=procurement_supplier_by_guid($supplierGuid);if(!$supplier||empty($supplier['active']))throw new RuntimeException('Choose an active supplier.');$clean=[];$total=0;foreach($lines as $line){$mg=trim((string)($line['material_guid']??''));$m=procurement_material_by_guid($mg);$qty=(float)($line['qty']??0);$cost=(int)round((float)($line['unit_cost']??0));if(!$m||$qty<=0||$cost<0)continue;$lineTotal=(int)round($qty*$cost);$clean[]=['guid'=>uuidv7(),'material_guid'=>$mg,'material_code'=>$m['code'],'material_name'=>$m['name'],'unit'=>$m['unit'],'qty_ordered'=>$qty,'qty_received'=>0.0,'unit_cost'=>$cost,'line_total'=>$lineTotal];$total+=$lineTotal;}if(!$clean)throw new RuntimeException('Add at least one valid purchase-order line.');$po=['guid'=>uuidv7(),'number'=>procurement_code('AWPO'),'supplier_guid'=>$supplierGuid,'supplier_snapshot'=>['code'=>$supplier['code'],'name'=>$supplier['name'],'gstin'=>$supplier['gstin']??''],'status'=>'DRAFT','lines'=>$clean,'total'=>$total,'notes'=>trim($notes),'created_at'=>gmdate('c'),'updated_at'=>gmdate('c'),'issued_at'=>null];procurement_mutate(function(array $s)use($po){$s['purchase_orders'][]=$po;return$s;},'procurement.po.create');return$po; }
function procurement_po_issue(string $guid): array { require_admin();$updated=null;procurement_mutate(function(array $s)use($guid,&$updated){foreach($s['purchase_orders'] as &$po)if(($po['guid']??'')===$guid){if(($po['status']??'')!=='DRAFT')throw new RuntimeException('Only a draft PO can be issued.');$po['status']='ISSUED';$po['issued_at']=gmdate('c');$po['updated_at']=gmdate('c');$updated=$po;break;}return$s;},'procurement.po.issue');if(!$updated)throw new RuntimeException('PO not found.');return$updated; }
function procurement_grn_receive(string $poGuid,array $received,string $deliveryRef=''): array { require_admin();$po=procurement_po_by_guid($poGuid);if(!$po||!in_array(($po['status']??''),['ISSUED','PART_RECEIVED'],true))throw new RuntimeException('PO is not open for receiving.');$grn=['guid'=>uuidv7(),'number'=>procurement_code('GRN'),'po_guid'=>$poGuid,'po_number'=>$po['number'],'supplier_guid'=>$po['supplier_guid'],'delivery_ref'=>trim($deliveryRef),'lines'=>[],'received_at'=>gmdate('c')];procurement_mutate(function(array $s)use($poGuid,$received,&$grn){$poIndex=null;foreach($s['purchase_orders'] as $i=>$x)if(($x['guid']??'')===$poGuid){$poIndex=$i;break;}if($poIndex===null)throw new RuntimeException('PO not found.');$po=&$s['purchase_orders'][$poIndex];foreach($po['lines'] as &$line){$qty=max(0,(float)($received[$line['guid']]??0));$remaining=max(0,(float)$line['qty_ordered']-(float)$line['qty_received']);if($qty<=0)continue;if($qty>$remaining+0.00001)throw new RuntimeException('Received quantity exceeds PO balance for '.$line['material_name'].'.');$line['qty_received']=(float)$line['qty_received']+$qty;$lot=['guid'=>uuidv7(),'lot_number'=>procurement_code('LOT'),'material_guid'=>$line['material_guid'],'material_code'=>$line['material_code'],'material_name'=>$line['material_name'],'unit'=>$line['unit'],'po_guid'=>$poGuid,'grn_guid'=>$grn['guid'],'qty_received'=>$qty,'qty_available'=>$qty,'qty_reserved'=>0.0,'qty_consumed'=>0.0,'unit_cost'=>(int)$line['unit_cost'],'quality_status'=>'ACCEPTED','received_at'=>gmdate('c')];$s['lots'][]=$lot;$grn['lines'][]=['po_line_guid'=>$line['guid'],'material_guid'=>$line['material_guid'],'material_name'=>$line['material_name'],'qty'=>$qty,'unit'=>$line['unit'],'unit_cost'=>$line['unit_cost'],'lot_guid'=>$lot['guid'],'lot_number'=>$lot['lot_number']];}if(!$grn['lines'])throw new RuntimeException('Enter at least one received quantity.');$all=true;$any=false;foreach($po['lines'] as $l){$any=$any||((float)$l['qty_received']>0);if((float)$l['qty_received']+0.00001<(float)$l['qty_ordered'])$all=false;}$po['status']=$all?'RECEIVED':($any?'PART_RECEIVED':'ISSUED');$po['updated_at']=gmdate('c');$s['grns'][]=$grn;return$s;},'procurement.grn.receive');return$grn; }
function procurement_stock_summary(): array { $s=procurement_store();$out=[];foreach($s['materials'] as $m){$on=0.0;$reserved=0.0;$value=0;foreach($s['lots'] as $lot)if(($lot['material_guid']??'')===$m['guid']&&($lot['quality_status']??'ACCEPTED')==='ACCEPTED'){$on+=(float)$lot['qty_available'];$reserved+=(float)$lot['qty_reserved'];$value+=(int)round(((float)$lot['qty_available']+(float)$lot['qty_reserved'])*(int)$lot['unit_cost']);}$out[]=['material'=>$m,'available'=>$on,'reserved'=>$reserved,'stock_value'=>$value,'below_reorder'=>$on<(float)($m['reorder_level']??0)];}return$out; }
function procurement_reserve_for_job(string $jobGuid,string $materialGuid,float $qty): array { require_admin();$job=makeos_job_by_guid($jobGuid);$m=procurement_material_by_guid($materialGuid);if(!$job)throw new RuntimeException('MakeOS job not found.');if(!$m)throw new RuntimeException('Material not found.');if(empty($job['bom_locked']))throw new RuntimeException('Lock the BOM before reserving inventory.');if($qty<=0)throw new RuntimeException('Reservation quantity must be greater than zero.');$reservation=['guid'=>uuidv7(),'job_guid'=>$jobGuid,'job_number'=>$job['number'],'material_guid'=>$materialGuid,'material_code'=>$m['code'],'material_name'=>$m['name'],'unit'=>$m['unit'],'qty'=>$qty,'allocations'=>[],'actual_cost'=>0,'status'=>'RESERVED','created_at'=>gmdate('c')];procurement_mutate(function(array $s)use(&$reservation,$qty,$materialGuid){$need=$qty;$idxs=[];foreach($s['lots'] as $i=>$lot)if(($lot['material_guid']??'')===$materialGuid&&($lot['quality_status']??'ACCEPTED')==='ACCEPTED'&&(float)($lot['qty_available']??0)>0)$idxs[]=$i;usort($idxs,fn($a,$b)=>strcmp((string)$s['lots'][$a]['received_at'],(string)$s['lots'][$b]['received_at']));$available=array_sum(array_map(fn($i)=>(float)$s['lots'][$i]['qty_available'],$idxs));if($available+0.00001<$qty)throw new RuntimeException('Insufficient accepted stock. Available: '.$available);foreach($idxs as $i){if($need<=0)break;$take=min($need,(float)$s['lots'][$i]['qty_available']);if($take<=0)continue;$s['lots'][$i]['qty_available']-=$take;$s['lots'][$i]['qty_reserved']+=$take;$cost=(int)round($take*(int)$s['lots'][$i]['unit_cost']);$reservation['allocations'][]=['lot_guid'=>$s['lots'][$i]['guid'],'lot_number'=>$s['lots'][$i]['lot_number'],'qty'=>$take,'unit_cost'=>$s['lots'][$i]['unit_cost'],'cost'=>$cost];$reservation['actual_cost']+=$cost;$need-=$take;}$s['reservations'][]=$reservation;return$s;},'procurement.reserve');return$reservation; }
function procurement_release_reservation(string $guid): array { require_admin();$updated=null;procurement_mutate(function(array $s)use($guid,&$updated){foreach($s['reservations'] as &$r)if(($r['guid']??'')===$guid){if(($r['status']??'')!=='RESERVED')throw new RuntimeException('Only reserved stock can be released.');foreach($r['allocations'] as $a){foreach($s['lots'] as &$lot)if(($lot['guid']??'')===($a['lot_guid']??'')){$q=(float)$a['qty'];$lot['qty_reserved']=max(0,(float)$lot['qty_reserved']-$q);$lot['qty_available']+=(float)$q;break;}}$r['status']='RELEASED';$r['released_at']=gmdate('c');$updated=$r;break;}return$s;},'procurement.reservation.release');if(!$updated)throw new RuntimeException('Reservation not found.');return$updated; }
function procurement_consume_job_reservations(string $jobGuid): array { require_admin();$count=0;procurement_mutate(function(array $s)use($jobGuid,&$count){foreach($s['reservations'] as &$r)if(($r['job_guid']??'')===$jobGuid&&($r['status']??'')==='RESERVED'){foreach($r['allocations'] as $a){foreach($s['lots'] as &$lot)if(($lot['guid']??'')===($a['lot_guid']??'')){$q=(float)$a['qty'];$lot['qty_reserved']=max(0,(float)$lot['qty_reserved']-$q);$lot['qty_consumed']+=(float)$q;break;}}$r['status']='CONSUMED';$r['consumed_at']=gmdate('c');$count++;}return$s;},'procurement.consume');return['count'=>$count]; }
function procurement_job_cost_variance(string $jobGuid): array { $job=makeos_job_by_guid($jobGuid);if(!$job)return['estimated'=>0,'actual'=>0,'variance'=>0];$estimated=makeos_bom_estimated_cost($job);$actual=0;foreach(procurement_reservations_for_job($jobGuid) as $r)if(in_array(($r['status']??''),['RESERVED','CONSUMED'],true))$actual+=(int)($r['actual_cost']??0);return['estimated'=>$estimated,'actual'=>$actual,'variance'=>$actual-$estimated]; }
function procurement_release_checks(): array { $s=procurement_store();$codes=[];$lotOk=true;$resOk=true;$poOk=true;foreach($s['materials'] as $m)$codes[]=$m['code']??'';foreach($s['lots'] as $l){if((float)($l['qty_available']??0)<-0.0001||(float)($l['qty_reserved']??0)<-0.0001||(float)($l['qty_consumed']??0)<-0.0001)$lotOk=false;}foreach($s['reservations'] as $r){$sum=array_sum(array_map(fn($a)=>(float)($a['qty']??0),$r['allocations']??[]));if(abs($sum-(float)($r['qty']??0))>0.0001)$resOk=false;}foreach($s['purchase_orders'] as $po)foreach($po['lines']??[] as $l)if((float)($l['qty_received']??0)>(float)($l['qty_ordered']??0)+0.0001)$poOk=false;$raw=is_file(procurement_file())?(string)file_get_contents(procurement_file()):'';$encrypted=$raw===''||!str_contains($raw,'purchase_orders');return [
 ['name'=>'Procurement encryption','ok'=>$encrypted,'detail'=>$encrypted?'Procurement store is encrypted at rest or uninitialized.':'Plaintext procurement data detected.'],
 ['name'=>'Material code uniqueness','ok'=>count($codes)===count(array_unique($codes)),'detail'=>'Raw-material codes must be unique.'],
 ['name'=>'Inventory non-negative invariant','ok'=>$lotOk,'detail'=>'Available/reserved/consumed quantities never become negative.'],
 ['name'=>'Reservation allocation integrity','ok'=>$resOk,'detail'=>'Every reservation equals the sum of its lot allocations.'],
 ['name'=>'PO receiving integrity','ok'=>$poOk,'detail'=>'Received quantities never exceed ordered quantities.'],
 ]; }
